var MsgKind = {
        Error            : 0x01000000,
        Warning          : 0x02000000,
        User             : 0x03000000,
        Log              : 0x04000000
};

// spool an informational message into the MSI log, if it is enabled.
function LogMessage(msg) {
    var record = Session.Installer.CreateRecord(0);
    record.StringData(0) = "CustomAction:: " + msg;
    Session.Message(MsgKind.Log, record);
}

///////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
// Helper functions
//
///////////////////////////////////////////////////////////////////////////////////////////////////////////////

///////////////////////////////////////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////////////////////////////////////
function trimStr(a_val)
{
    return a_val.replace(/^\s+|\s+$/g, '');
}


///////////////////////////////////////////////////////////////////////////////////////////////////////////////
///////////////////////////////////////////////////////////////////////////////////////////////////////////////
function validateIPv4(a_val)
{
    LogMessage("validateIPv4() - '" + a_val + "'");
    return /^\b(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(\.(25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)){3}\b$/i.test(a_val);
}

function validateFQDN(a_val)
{
      LogMessage("validateIPv6() - '" + a_val + "'");

      // enforce 255 characters limit
      if(a_val.length > 255) {
          return false;
      }

      // only digits and dots
      if(/^([\d\.]+)$/i.test(a_val)) {
          return false;
      }

      return /^([\w\d]\.|[\w\d][-\w\d_]{0,61}[\w\d]\.)*([\w\d]|[\w\d][-\w\d_]{0,61}[\w\d])$/i.test(a_val);
}

function validatePort(val)
{
    return (val > 0) && (val < 65535);
}

function validateItem(val)
{
    var split = val.split(':');
    if (split.length > 2) {
        return false;
    }

    if (!validateIPv4(split[0]) && !validateFQDN(split[0])) {
        return false;
    }

    if (split.length > 1) {
        return validatePort(split[1]);
    }
    return true;
}

function VerifyExclusionAddresses()
{
    LogMessage("VerifyExclusionAddresses() - enter");

    Session.Property("EXCLUSION_VALUES_VALID") = "0";

    var validEntries = 0;

    for(var i=0; i<9; i++) {
        var index = "IP" + i;
        Session.Property(index) = trimStr(Session.Property(index));
        var val = Session.Property(index);

        if(val.length == 0) {
            continue;
        }

        if(!validateItem(val)) {
            LogMessage("Value " + index + " is invalid. Please specify a valid IPv4 value");
            Session.property(index) = "";
        }
        validEntries++;
    }

    Session.Property("EXCLUSION_VALUES_VALID") = "1";

    LogMessage("VerifyExclusionAddresses() - exit");
    return 1;
}

